    "specialty": "一、杜氏骨伤科特色诊疗（核心传承）  杜氏骨伤科历经数代传承，积淀了 “手法精要、方药独到、内外兼治” 的诊疗体系，注重 “正骨先正筋、治伤必活血” 的核心理念，在骨伤科领域独树一帜。  1.传统正骨手法（杜氏核心技艺）：传承杜氏 “轻、巧、准、稳” 的正骨精髓，针对各类四肢闭合性骨折、关节脱位，无需手术，通过徒手精准复位，快速恢复骨骼正常力线与关节对位。复位后搭配杜氏定制木质夹板、医用支具固定，贴合肢体生理曲线，既稳固骨折部位，又不束缚气血运行，实现 “无创复位、微创恢复”，创伤更小、恢复更快，最大程度保留肢体原生功能。  2.脊柱筋骨调衡（杜氏特色手法）：延续杜氏 “脊柱为纲、筋骨同调” 的调理思路，运用特色正脊正骨手法，精准调…",
    "profile": "https://www.pkuih.edu.cn/medical-team/details_936_97123.html",
    "expert": false,
    "photo": "./assets/team/97123.webp"
