    "specialty": "一、心血管疾病（核心专长） 以中医 “胸痹”“眩晕” 理论为核心，中西医协同调治： 1.冠心病、心绞痛：结合西医冠脉评估，辨证 “气虚血瘀、心阳不足”，经方活血化瘀、益气养心，缓解胸闷心悸、胸痛，改善心肌供血。 2.高血压、高脂血症：西医把控指标，中医针对“肝阳上亢、痰湿内阻、肝肾阴虚”，平肝潜阳、健脾祛湿、滋阴补肾，平稳指标，减少靶器官损害。 3.急慢性心力衰竭：西医规范治疗基础上，辨证“心肾阳虚、水湿内停”，温阳利水、益气活血，缓解喘促、水肿、乏力，延缓心功能恶化。 二、情志与睡眠障碍 立足 “心神失养、肝气郁结”，身心同调： 1.失眠：辨证心脾两虚、肝肾阴虚、痰热扰心等证型，经方益气养血、滋阴安神，搭配情志疏导，改善入睡困难、…",
