    "specialty": "主动脉疾病，包括胸主动脉瘤、腹主动脉瘤、主动脉夹层、腹主动脉闭塞等。静脉疾病，包括门静脉高压、布加氏综合征、髂静脉压迫综合征、上腔静脉阻塞综合征、深静脉血栓、静脉曲张等。内脏动脉疾病，包括肠系膜动脉夹层或栓塞、肾动脉狭窄或闭塞、内脏动脉瘤等。弓上动脉疾病，包括颈动脉狭窄、椎动脉狭窄、锁骨下动脉狭窄或闭塞等。下肢动脉硬化闭塞症、下肢动脉栓塞、脉管炎等。血管畸形、血管瘤。各种良恶性肿瘤的介入治疗，如肝癌、子宫肌瘤、梗阻性黄疸、食管狭窄等",
