    "specialty": "一、呼吸系统病症调理 专攻急慢性咳嗽、哮喘、慢性支气管炎、慢阻肺、肺纤维化、肺结节、咽痒咳嗽等呼吸系统问题，尤其擅长调理气道高反应性咳嗽（含咳嗽变异性哮喘、过敏性咳嗽等）。中医认为此类病症多与 “外邪犯肺、肺气上逆、肺阴亏虚” 相关，肺结节则核心是 “肺脾肾虚损为本，痰瘀气滞郁结于肺”。通过祛风解痉、宣降肺气、润肺止咳，或化痰散结、理气通络、补益肺脾等治法，搭配个性化方药，既能缓解咳嗽、咽痒、气短等不适，又能调理脏腑机能，从根源改善肺部状态。 二、消化系统病症调理 针对慢性胃炎（胃胀、胃痛、消化不良）、胃食管反流病、慢性腹泻、肠易激综合征、便秘等消化系统问题，聚焦 “脾胃功能失调、气血运行不畅、湿浊内蕴” 等核心病机。以健脾和胃、理…",
