    "specialty": "主要从事各类先天性心脏病的外科治疗。特别在新生儿、婴幼儿、成人、再次、复杂先天性心脏病的诊治领域具有丰富的经验。尤其右腋下微创小切口的简单先心病及部分复杂先心病的诊治，以及右室流出道重建相关先心病，如法洛四联症、右室双出口、肺动脉闭锁、肺动脉狭窄的诊治和三尖瓣下移、完全性心内膜垫缺损等的瓣膜修复治疗。在国内率先开展杂交式治疗先心病术后肺动脉瓣狭窄或返流相关疾病，扩大了介入瓣膜在先天性心脏病中的临床适应症",
