    "specialty": "一、心脑血管系统疾病（主打强项） 以中医 “心主血脉、脑为髓海” 理论为核心，专攻心脑血管相关病症： 1.心脏疾患：冠心病、心绞痛、心肌供血不足，及心慌心悸、胸闷胸痛、气短乏力等，辨证多属 “气虚血瘀、心阳不足、痰湿痹阻”，通过益气活血、温通心阳、化痰通络，改善心肌供血，缓解胸部不适。 2.术后调养：心脏支架术后体质恢复，针对术后气血瘀滞、脏腑机能受损，侧重益气化瘀、扶正固本，调理胸闷乏力，修复脏腑功能，降低复发风险。 3.心律异常：早搏、房颤等心律失常，围绕 “心神失养、气血失调、痰湿扰心” 辨证，以宁心安神、益气养血、化痰定悸为法，改善心慌不安、心跳紊乱。 4.血管病变：颈动脉斑块、血管硬化、血脉瘀堵，遵循 “活血化瘀、软坚散结…",
