    "specialty": "一、呼吸系统疾病（主攻方向） 遵循肺主宣降理论，中西医结合专项诊治各类呼吸系统疑难病症： 1.咳喘病症：诊治久咳、顽固性咳嗽、咳嗽变异性哮喘，辨证施治，宣肺润燥、解痉止咳，修复肺脏功能。 2.气道顽疾：调理过敏性、运动性、支气管哮喘，固本补虚、化痰平喘，联合西医控症，减少发病、降低复发率。 3.肺部慢病：调治慢阻肺、肺气虚所致气短乏力，补肺健脾、益气通络，提升肺功能与身体耐受力。 4.疑难肺病：干预间质性肺病、肺纤维化，滋阴益肾、化痰散瘀，缓解胸闷干咳，延缓病情发展。 5.肺癌专项调理：针对肺部术后、放化疗后不适，固本培元，改善体虚咳喘，归入术后康复板块统筹施治。 6.鼻肺同源疾病：论治过敏性鼻炎、鼻源性咳喘，脏腑同调，改善过敏体质…",
