    "hospital": "北京大学国际医院",
    "specialty": "一、肾系及泌尿病症调理  专攻各类肾脏疾病、免疫相关肾病、痛风、尿路感染、泌尿系结石等泌尿肾系疾患。中医认为此类病症多与脾肾亏虚、湿热浊毒内蕴、瘀血阻滞下焦、免疫失调、水液代谢失常相关，系统性红斑狼疮性肾炎、紫癜性肾炎多为本虚标实，正气亏虚兼热毒瘀阻。通过益肾固本、清利湿热、泄浊解毒、化瘀排石、调和免疫等治法，搭配个性化方药，改善血尿、蛋白尿、腰痛、关节肿痛、排尿异常等不适，顾护脾肾本源，调节机体免疫，改善肾脏及泌尿机能。 二、免疫与肺系病症调理  针对过敏、哮喘、风湿类风湿关节炎等免疫相关疾患。中医病机多责之于肺卫不固、风邪伏络、肝肾亏虚、痹阻经络、正气不足。采用补肺固卫、祛风脱敏、化痰平喘、补益肝肾、祛风除湿、活血通络等治法，个…",
    "profile": "https://www.pkuih.edu.cn/medical-team/details_936_97825.html",
