    "specialty": "一、高血压病调理 针对老年性、更年期女性、青年初发高血压，及高血压合并心脑肾损害、动脉粥样硬化等，辨证 “肝肾 阴虚、肝阳上亢、痰湿内阻、气血瘀滞” 等病机。以平肝潜阳、滋阴补肾、健脾祛湿、活血化瘀等治法 配伍方剂，平稳控压的同时滋养脏腑、疏通经络，减少靶器官损伤，缓解头晕、头痛等不适。尤其针对更年期女性，兼顾疏肝理气、养血调经与降压，适配体质特点。 二、冠心病调理 涵盖心绞痛、心肌梗死、支架 / 搭桥术后再狭窄及心脏神经官能症，辨证 “气虚血瘀、痰浊痹阻、心 阳不足”。采用益气活血、化痰通络、温通心阳等治法，疏畅冠脉气血、滋养心肌，缓解胸闷、胸痛、心悸；术后侧重益气化瘀、软坚散结，降低再狭窄风险；神经官能症则兼顾疏肝理气、宁心安神…",
