    "specialty": "一、心脑血管疾病经方调治 擅用经典经方调治高血压、脑梗死、脑出血、后循环缺血性眩晕、冠心病、冠脉支架植入术后再狭窄、心律失常、心力衰竭等心脑血管疾患。此类病症病机多为痰瘀阻络、气血亏虚、阴阳失调、心脉痹阻。以通脉活血、化痰逐瘀、调和气血、燮理阴阳为主要治法，个体化配伍经方方药，缓解头晕眩晕、胸闷胸痛、心悸心慌、肢体不利等不适，维护心脉脑络功能，降低疾病复发风险。 二、代谢与肝肾消化系统病症调理 调治糖尿病、糖尿病肾病、转氨酶升高、慢性肝病、胆囊炎、胆结石等代谢及肝胆脾胃消化系统疾病。本类疾病常由气阴两虚、湿热内蕴、肝郁脾虚、痰浊瘀阻所致。采用益气养阴、清利湿热、疏肝健脾、利胆化石、护肾固元治法，辨证施方，改善口干多饮、胁肋胀痛、胃脘…",
