    "specialty": "一、脾胃病（消化系统疾病）调理  专攻慢性胃炎、萎缩性胃炎、胃溃疡、消化不良、反流性食管炎、慢性结肠炎、腹胀、腹泻、便秘等消化系统病症。中医认为此类病症多与脾胃运化失司、气机升降失常、湿浊内蕴相关，脾虚证、脾虚湿蕴证、痰湿证为本病常见核心证型。通过健脾和胃、消疡护膜、理气化滞、化湿和中、润肠通腑等治法，搭配个性化方药，既能缓解胃痛反酸、腹胀便溏、大便秘结等不适，又能顾护脾胃本源，恢复中焦运化平衡，从根源调护胃肠机能。 二、肺系病（呼吸系统疾病）调理  针对急性咳嗽、慢性咳嗽、过敏性咳嗽、过敏性鼻炎、过敏性哮喘、慢性阻塞性肺疾病稳定期等肺系疾患。中医认为该类疾患常责之于肺气宣降失常、肺气不足、肺经郁热、肺热痰盛。采用宣肺肃降、祛风脱敏…",
