    "specialty": "生殖内分泌、诱导排卵、超促排卵、不孕不育相关诊疗、4D 输卵管超声造影技术、试管婴儿及人工授精等辅助生殖技术主要从事女性不孕不育及生殖内分泌方面的诊疗工作。熟练掌握女性生殖内分泌学临床专业知识，特别是各种促排卵药物的使用和月经周期的激素调控。对内分泌紊乱、月经不调、排卵障碍类疾病，如多囊卵巢综合征（PCOS）、卵泡未破裂黄素化（Lufs）及反复流产等积累了相当多的诊疗经验。能够熟练进行宫腹腔镜操作及OHSS 的诊治。对各种超促排卵方案的制定及IVF-ET、AI 等辅助生殖技术具有丰富的临床经验",
