    "specialty": "一、声光电美容、微创抗衰、瘢痕及皮肤肿物诊疗 1. 色素病变：雀斑、黄褐斑、术后色沉、太田痣、颧部褐青色痣、各类复杂性色斑，不良文身 2. 血管皮损：毛细血管扩张、鲜红斑痣等血管畸形 3. 问题肌管理：玫瑰痤疮、痤疮、敏感肌屏障综合修护，痤疮后瘢痕 4. 光电抗衰：热玛吉、热拉提、射频微针及超声抗衰，改善眼周、面颈部松弛下垂 5. 瘢痕综合修复：增生瘢痕、术后创伤瘢痕 6. 肤质形体管理：面部美白紧致、无创身体减脂塑形 7、产后修复：盆底肌及腹直肌修复，阴道松弛，妊娠纹，私密部色素沉着 二、注射美容与整形手术 1. 肉毒素诊疗：改善动态皱纹、多汗症；面部轮廓塑形、瘦腿、瘦肩 2. 填充注射：泪沟、眶周细纹、法令纹、颈纹填充，基础水光…",
