    "hospital": "北京大学国际医院",
    "specialty": "一、心脑血脉病症调理 专攻冠心病、心律失常、心脏神经官能症、头痛、眩晕头晕等心脑血脉类疾患。中医认为此类病症多与心脉痹阻、气血亏虚、气机失调、清窍失养、肝肾阴阳失衡相关。通过益气活血、通脉宁心、平肝息风、养血定眩等治法，搭配个性化方药，改善胸闷心悸、心慌失眠、头目胀痛眩晕等不适，调和气血血脉，安定心神，恢复脏腑阴阳平衡。 二、脾胃消化疾病调理 针对各类脾胃病、胆囊结石等消化系统疾患。本类疾病病机多责之于脾胃运化失司、肝胆疏泄失常、湿浊痰瘀蕴结中焦。以健脾和胃、疏肝利胆、理气消胀、化痰散结为主要治法，运用经方时方辨证配伍，缓解胃脘不适、胁肋胀痛、纳差腹胀等症状，调和肝胆脾胃机能，疏利肝胆气机。 三、妇科相关疾病调理 调治月经不调、子宫…",
