    "specialty": "成人/儿童包皮过长、包茎精细化整形手术及非手术治疗，注重术后美观与舒适度；精通输尿管软镜、经皮肾镜等结石微创术式、，开展前列腺增生激光、电切微创手术；对肾癌、膀胱癌、前列腺癌等泌尿肿瘤，可提供微创手术、药物、随访一体化综合治疗，擅长各类泌尿生殖系肿瘤规范化综合治疗，处理各类泌尿外科常见及疑难病症。临床操作轻柔，诊疗方案个体化，兼顾疗效与就医体验",
